import os, signal
cur = os.getpid()
for pid in os.listdir('/proc'):
    if not pid.isdigit():
        continue
    pid_int = int(pid)
    if pid_int == cur:
        continue
    try:
        with open(f'/proc/{pid}/cmdline','rb') as f:
            cmd = f.read().decode(errors='ignore').replace('\x00',' ')
    except Exception:
        continue
    if 'python' in cmd and 'survey_dirty.csv' in cmd:
        try:
            os.kill(pid_int, signal.SIGKILL)
            print('killed', pid_int)
        except Exception as e:
            print('failed', pid_int, e)
